//! Parity and regression tests for the Breeze TTS 2 family.
//!
//! Pinned fixtures reside in `testdata/tts_breeze_tts/`, generated by
//! `tools/gen_breeze_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference Model at tiny seeded dims (mock
//! tokenizer and audio tokenizer), so the traces carry the reference
//! prompt embeddings, text-encoder states, depth-head logits, greedy
//! frame loops, and the sampler stage math.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{GenerateParams, Model, ModelConfig, ReferencePrompt, StopReason};
use crate::tts::sampling;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_breeze_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Masked logit entries use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen (prompt builds 2.8e-6, text encoder 1.1e-5, depth
/// head 9.5e-7, sampler stages exact); assertions use these values, not
/// re-measured ones.
const EMBED_TOLERANCE: f32 = 2e-5;
const LOGIT_TOLERANCE: f32 = 1e-4;

fn generate_model() -> Model {
    Model::open(&testdata("generate")).expect("family model loads")
}

fn greedy_params(max_tokens: usize, cfg_scale: Option<f32>) -> GenerateParams {
    GenerateParams {
        max_tokens,
        temperature: 0.0,
        top_p: 1.0,
        top_k: 0,
        repetition_penalty: 1.0,
        cfg_scale,
    }
}

#[test]
fn family_config_reads_the_wrapper_aliases_and_defaults() {
    let fixture_config = read_json(&testdata("generate/config.json"));
    let config = ModelConfig::from_json(&fixture_config).unwrap();
    assert_eq!(config.num_codebooks, 4);
    assert_eq!(config.vocab_size, 64);
    // codec_config absent: codec_vocab_size defaults to vocab - 3.
    assert_eq!(config.codec_vocab_size, 61);
    assert_eq!(config.backbone.hidden_size, 32);
    assert_eq!(config.backbone.num_hidden_layers, 2);
    assert!(config.backbone.qk_norms);
    assert_eq!(config.audio_embed_size, 8);
    assert_eq!(config.text_vocab_size, 128);
    assert_eq!(config.text_encoder.hidden_size, 16);
    // Pattern 3 over 3 layers: two sliding, one full.
    assert_eq!(config.text_encoder.layer_types, vec![false, false, true]);
    assert_eq!(config.text_encoder.rope_theta_sliding, 10000.0);
    assert_eq!(config.text_encoder.rope_theta_full, 1000000.0);
    assert_eq!(config.depth_decoder.hidden_size, 16);
    assert_eq!(config.depth_decoder.num_codebooks, 4);
    assert_eq!(config.sample_rate, 24000);
    assert_eq!(config.codebook_eos_token_id, 0);

    // The dataclass defaults when nothing is set.
    let defaults = ModelConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(defaults.num_codebooks, 16);
    assert_eq!(defaults.vocab_size, 2051);
    assert_eq!(defaults.codec_vocab_size, 2048);
    assert_eq!(defaults.backbone.hidden_size, 2048);
    assert_eq!(defaults.text_encoder.vocab_size, 262208);
    assert_eq!(defaults.depth_decoder.hidden_size, 1024);
    assert_eq!(defaults.sample_rate, 24000);

    // Explicit audio_* aliases win over the wrapper fields.
    let aliased = ModelConfig::from_json(&serde_json::json!({
        "num_codebooks": 3,
        "vocab_size": 9,
        "audio_num_codebooks": 5,
        "audio_vocab_size": 11,
    }))
    .unwrap();
    assert_eq!(aliased.num_codebooks, 5);
    assert_eq!(aliased.vocab_size, 11);
    assert_eq!(aliased.codec_vocab_size, 8);

    // The codec codebook_size gate refuses an out-of-range value.
    let refused = ModelConfig::from_json(&serde_json::json!({
        "vocab_size": 10,
        "codec_config": {"codebook_size": 11},
    }))
    .unwrap_err();
    assert!(
        refused
            .to_string()
            .contains("between 1 and the wrapper vocab_size"),
        "{refused}"
    );
}

#[test]
fn prompt_embeddings_match_the_reference_builds() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = generate_model();
    let hidden = model.config.backbone.hidden_size;

    let plain = model
        .prompt_embeddings(&i32_vec(&traces["plain"]["ids"]), None)
        .expect("plain prompt");
    let want = f32_vec(&traces["plain"]["embeddings"]);
    assert_eq!(plain.len(), want.len());
    assert_eq!(want.len() / hidden, i32_vec(&traces["plain"]["ids"]).len());
    let diff = max_abs_diff(&plain, &want);
    assert!(diff <= EMBED_TOLERANCE, "plain prompt diff {diff}");

    // Instruct: the conditional build (with the marker ids) and the
    // instruct-free pass the guidance combines against.
    let cond = model
        .prompt_embeddings(&i32_vec(&traces["instruct"]["cond_ids"]), None)
        .expect("cond prompt");
    let diff = max_abs_diff(&cond, &f32_vec(&traces["instruct"]["cond_embeddings"]));
    assert!(diff <= EMBED_TOLERANCE, "cond prompt diff {diff}");
    let uncond = model
        .prompt_embeddings(&i32_vec(&traces["instruct"]["uncond_ids"]), None)
        .expect("uncond prompt");
    let diff = max_abs_diff(&uncond, &f32_vec(&traces["instruct"]["uncond_embeddings"]));
    assert!(diff <= EMBED_TOLERANCE, "uncond prompt diff {diff}");

    // Voice clone: the reference turn rides the audio embedding, the
    // codebook-EOS frame follows it.
    let reference = ReferencePrompt {
        text_ids: i32_vec(&traces["reference"]["text_ids"]),
        codes: i32_rows(&traces["reference"]["codes"]),
    };
    let with_ref = model
        .prompt_embeddings(&i32_vec(&traces["plain"]["ids"]), Some(&reference))
        .expect("reference prompt");
    let want = f32_vec(&traces["reference"]["embeddings"]);
    assert_eq!(with_ref.len(), want.len());
    let diff = max_abs_diff(&with_ref, &want);
    assert!(diff <= EMBED_TOLERANCE, "reference prompt diff {diff}");
    // Rows: ref text + 4 code frames + eos frame + target text.
    assert_eq!(
        with_ref.len() / hidden,
        reference.text_ids.len()
            + reference.codes[0].len()
            + 1
            + i32_vec(&traces["plain"]["ids"]).len()
    );
    // A reference prompt with the wrong codebook count is refused.
    let bad = ReferencePrompt {
        text_ids: vec![1],
        codes: vec![vec![1, 2], vec![3, 4]],
    };
    let error = model
        .prompt_embeddings(&i32_vec(&traces["plain"]["ids"]), Some(&bad))
        .unwrap_err();
    assert!(error.to_string().contains("codebooks"), "{error}");
}

#[test]
fn text_encoder_matches_the_reference_states() {
    let traces = read_json(&testdata("math/traces.json"));
    let model = generate_model();
    for name in ["text_encoder_short", "text_encoder_long"] {
        let case = &traces[name];
        let got = model
            .text_encoder
            .forward(&i32_vec(&case["ids"]))
            .expect("encodes");
        let want = f32_vec(&case["hidden"]);
        let diff = max_abs_diff(&got, &want);
        assert!(diff <= LOGIT_TOLERANCE, "{name} hidden diff {diff}");
    }
}

#[test]
fn audio_frame_embedding_matches_the_reference() {
    let traces = read_json(&testdata("math/traces.json"));
    let model = generate_model();
    let got = model
        .embed_audio_frame(&i32_vec(&traces["audio_frame_embed"]["codes"]))
        .expect("embeds");
    let diff = max_abs_diff(&got, &f32_vec(&traces["audio_frame_embed"]["embedding"]));
    assert!(diff <= EMBED_TOLERANCE, "audio frame embed diff {diff}");
    // Wrong codebook counts are refused by name.
    let error = model.embed_audio_frame(&[1, 2, 3]).unwrap_err();
    assert!(error.to_string().contains("must carry 4 codes"), "{error}");
}

#[test]
fn depth_head_mapping_matches_the_reference_logits() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = generate_model();
    for (index, case) in traces["depth_head"]
        .as_array()
        .expect("rows")
        .iter()
        .enumerate()
    {
        let token_ids = i32_vec(&case["token_ids"]);
        assert_eq!(token_ids[0], 0, "the placeholder rides position zero");
        assert_eq!(token_ids.len(), index + 2, "head index tracks the length");
        let hidden = f32_vec(&case["backbone_hidden"]);
        let got = model
            .depth_decoder
            .next_logits(&token_ids, &hidden)
            .expect("next logits");
        let diff = max_abs_diff(&got, &f32_vec(&case["logits"]));
        assert!(diff <= LOGIT_TOLERANCE, "depth row {index} diff {diff}");
    }
    // The placeholder-plus-one-code minimum and the head range are
    // enforced.
    let hidden = vec![0.1f32; model.config.depth_decoder.backbone_hidden_size];
    let error = model.depth_decoder.next_logits(&[0], &hidden).unwrap_err();
    assert!(
        error.to_string().contains("at least one codebook token"),
        "{error}"
    );
    let error = model
        .depth_decoder
        .next_logits(&[0, 1, 2, 3, 4], &hidden)
        .unwrap_err();
    assert!(error.to_string().contains("heads"), "{error}");
}

#[test]
fn reserved_mask_and_sample_match_the_reference() {
    let traces = read_json(&testdata("math/traces.json"));
    let model = generate_model();
    let logits = f32_vec(&traces["mask_reserved"]["logits"]);
    let mut masked = logits.clone();
    model.mask_reserved_codec_logits(&mut masked);
    let diff = max_abs_diff(&masked, &f32_vec_masked(&traces["mask_reserved"]["masked"]));
    assert!(diff <= LOGIT_TOLERANCE, "mask diff {diff}");
    // The reserved band is exactly [codec_vocab_size, vocab_size).
    assert!(masked[..model.config.codec_vocab_size]
        .iter()
        .all(|value| value.is_finite()));
    assert!(
        masked[model.config.codec_vocab_size..model.config.vocab_size]
            .iter()
            .all(|v| v.is_infinite())
    );
    assert!(
        masked[model.config.vocab_size].is_finite(),
        "the EOS class survives"
    );

    for allow_eos in [true, false] {
        // The generator keys these with Python str(bool): True / False.
        let key = if allow_eos {
            "sample_allow_eos_True"
        } else {
            "sample_allow_eos_False"
        };
        let case = &traces[key];
        let valid = model.config.vocab_size + usize::from(allow_eos);
        let sliced = masked[..valid].to_vec();
        let logprobs = sampling::log_softmax(&sliced);
        let diff = max_abs_diff(&logprobs, &f32_vec_masked(&case["logprobs"]));
        assert!(
            diff <= LOGIT_TOLERANCE,
            "allow_eos {allow_eos} logprobs diff {diff}"
        );
        let got = model
            .sample(
                &logits,
                &greedy_params(4, None),
                allow_eos,
                crate::music::minimax_music3::rng::Key::new(0),
            )
            .expect("samples");
        assert_eq!(got, case["argmax"].as_u64().unwrap() as usize);
    }
}

#[test]
fn repetition_penalty_matches_the_reference() {
    let traces = read_json(&testdata("math/traces.json"));
    let model = generate_model();
    let case = &traces["repetition_penalty"];
    let mut logits = f32_vec(&case["logits"]);
    model
        .apply_repetition_penalty(&mut logits, &i32_vec(&case["generated"]), 1.7)
        .expect("applies");
    let diff = max_abs_diff(&logits, &f32_vec(&case["penalized"]));
    assert!(diff <= LOGIT_TOLERANCE, "penalty diff {diff}");
    // Penalty 1.0 is the documented no-op.
    let mut untouched = f32_vec(&case["logits"]);
    model
        .apply_repetition_penalty(&mut untouched, &[1, 2, 3], 1.0)
        .unwrap();
    assert_eq!(untouched, f32_vec(&case["logits"]));
}

fn plain_ids() -> Vec<i32> {
    i32_vec(&read_json(&testdata("generate/traces.json"))["plain"]["ids"])
}

#[test]
fn greedy_generation_stops_at_eos_with_reference_frames() {
    let traces = read_json(&testdata("generate/traces.json"));
    let scenario = &traces["scenarios"][0];
    let mut model = generate_model();
    let got = model
        .generate(&plain_ids(), None, None, &greedy_params(24, None), 0)
        .expect("generate");
    assert_eq!(got.frames, i32_rows(&scenario["frames"]));
    assert_eq!(got.stopped_by, StopReason::EndOfText);
}

#[test]
fn greedy_generation_stops_at_max_tokens() {
    let traces = read_json(&testdata("generate/traces.json"));
    let scenario = &traces["scenarios"][1];
    let mut model = generate_model();
    let got = model
        .generate(&plain_ids(), None, None, &greedy_params(6, None), 0)
        .expect("generate");
    assert_eq!(got.frames, i32_rows(&scenario["frames"]));
    assert_eq!(got.stopped_by, StopReason::MaxTokens);
}

#[test]
fn greedy_generation_runs_classifier_free_guidance() {
    let traces = read_json(&testdata("generate/traces.json"));
    let scenario = &traces["scenarios"][2];
    let mut model = generate_model();
    let got = model
        .generate(
            &i32_vec(&traces["instruct"]["cond_ids"]),
            Some(&i32_vec(&traces["instruct"]["uncond_ids"])),
            None,
            &greedy_params(24, Some(2.0)),
            0,
        )
        .expect("generate");
    assert_eq!(got.frames, i32_rows(&scenario["frames"]));
    assert_eq!(got.stopped_by, StopReason::MaxTokens);

    // Guidance with a scale of 1.0 is the documented no-op: the
    // instruct prompt with an uncond pass matches the plain run
    // trajectory shape (here: the same stop reason and frame count on
    // the plain prompt).
    let mut unity = generate_model();
    let unity_frames = unity
        .generate(
            &plain_ids(),
            Some(&plain_ids()),
            None,
            &greedy_params(6, Some(1.0)),
            0,
        )
        .expect("unity guidance");
    let mut plain = generate_model();
    let plain_frames = plain
        .generate(&plain_ids(), None, None, &greedy_params(6, None), 0)
        .expect("plain");
    assert_eq!(unity_frames.frames, plain_frames.frames);
    assert_eq!(unity_frames.stopped_by, plain_frames.stopped_by);
}

#[test]
fn eos_first_model_stops_immediately() {
    let traces = read_json(&testdata("generate_eos/traces.json"));
    let mut model = Model::open(&testdata("generate_eos")).expect("eos model loads");
    let got = model
        .generate(
            &i32_vec(&traces["ids"]),
            None,
            None,
            &greedy_params(4, None),
            0,
        )
        .expect("generate");
    assert!(got.frames.is_empty());
    assert_eq!(got.stopped_by, StopReason::EndOfText);
}

#[test]
fn generate_validates_the_reference_guards() {
    let ids = plain_ids();
    let base = greedy_params(4, None);
    let expect = |params: GenerateParams| -> String {
        let mut model = generate_model();
        model
            .generate(&ids, None, None, &params, 0)
            .unwrap_err()
            .to_string()
    };
    assert!(expect(GenerateParams {
        max_tokens: 0,
        ..base.clone()
    })
    .contains("max_tokens"));
    assert!(expect(GenerateParams {
        top_k: -1,
        ..base.clone()
    })
    .contains("top_k"));
    assert!(expect(GenerateParams {
        temperature: -0.5,
        ..base.clone()
    })
    .contains("temperature"));
    assert!(expect(GenerateParams {
        top_p: 1.5,
        ..base.clone()
    })
    .contains("top_p"));
    assert!(expect(GenerateParams {
        repetition_penalty: 0.0,
        ..base.clone()
    })
    .contains("repetition_penalty"));
    assert!(expect(GenerateParams {
        cfg_scale: Some(f32::NAN),
        ..base
    })
    .contains("cfg_scale"));
    // A reference prompt with the wrong codebook count is refused.
    let mut model = generate_model();
    let bad_reference = ReferencePrompt {
        text_ids: ids.clone(),
        codes: vec![vec![1, 2], vec![3, 4]],
    };
    let error = model
        .generate(&ids, None, Some(&bad_reference), &greedy_params(4, None), 0)
        .unwrap_err();
    assert!(error.to_string().contains("codebooks"), "{error}");
}
